  "findings": [
    {
      "locator": "Section 5.2 / Section 6",
      "issue": "Example B is required to be a fully populated synthetic example, but the completeness calculation states one required field (committee-opinion attachment location) is missing, making the example 87.5% complete.",
      "correction": "Make Example B fully populated with all required field locations, then update Section 6 to 8/8 = 100% and adjust the related audit-trail status accordingly."
    },
    {
      "locator": "Section 11 replacement register",
      "issue": "Synthetic IDs used in the body are not all individually registered (e.g., SYN-FRM-001, SYN-ATT-000, SYN-REG-001, SYN-WR-0048-I10-E03-R01), and SYN-DL-001/002 is combined into one row.",
      "correction": "Add one register row for every synthetic fact, including value, location, type, authentic source, and responsible role; split combined deadline rows."
    },
    {
      "locator": "Section 6",
      "issue": "The required-field denominator is stated as 8 but the specific 8 required fields are not defined, so the numerator/denominator calculation is not auditable.",
      "correction": "Add an explicit required-field list for Example A and Example B before the completeness formula."
    },
    {
      "locator": "Whole document",
      "issue": "The deliverable contains simplified Chinese characters in a Traditional Chinese document (e.g., 替换, 専屬, 规则, 与, 定义, 带, 宣称).",
      "correction": "Convert all simplified characters to Traditional Chinese equivalents without changing meaning."
    },
    {
      "locator": "30-second explanation",
      "issue": "The phrase “附中附件位置” is unclear/typographical.",
      "correction": "Replace it with “附上附件位置” or equivalent clear wording."
    }
  ],
  "checked_at": "2026-11-18"
}
